NjEsOSBAQCBzdHJ1Y3QgaGVudHJ5KiBBZmZpeE1ncjo6Y29tcG91bmRfY2hlY2soY29uc3Qgc3Rk
OjpzdHJpbmcmIHdvcmQsCiAgICAgICAgIGkgPSBzb2xkaTsKICAgICAgICAgc3QuYXNzaWduKHdv
